<?php use Passport\Copy; use Passport\Rules; ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Okwethu - <?= $e($title) ?></title><style>
@page {margin:34px 38px 88px;} body {font-family:"DejaVu Sans",sans-serif;color:#332513;font-size:10px;line-height:1.55;} h1 {font-size:28px;line-height:1.18;margin:12px 0 10px;word-wrap:break-word;} h2 {font-size:14px;line-height:1.3;margin:22px 0 8px;} p {margin:6px 0 10px;word-wrap:break-word;} a {color:#79500E;text-decoration:none;word-wrap:break-word;} .brand {width:220px;} .topbar {height:7px;background:#DAA520;margin-bottom:16px;} .eyebrow {font-size:8px;letter-spacing:2px;color:#79500E;font-weight:bold;} .hero {background:#FFEAAB;padding:18px 20px;margin:12px 0 18px;} .meta {width:100%;border-collapse:collapse;table-layout:fixed;} .meta td {width:50%;vertical-align:top;padding:9px 12px;border-bottom:1px solid #E8D8B2;word-wrap:break-word;} .label {font-size:8px;text-transform:uppercase;letter-spacing:1px;color:#79500E;} .value {font-size:11px;font-weight:bold;} .notice {padding:13px 16px;background:#FFF4D2;border-left:4px solid #DAA520;margin:18px 0;font-size:9px;} .qr-card {width:100%;border-collapse:collapse;background:#FFFBF1;border:1px solid #E8D8B2;margin:15px 0;table-layout:fixed;} .qr-card td {padding:12px;vertical-align:middle;} .qr-cell {width:25%;text-align:right;} .qr {width:100px;height:100px;} .tag {font-size:9px;color:#79500E;} .data {width:100%;border-collapse:collapse;table-layout:fixed;} .data th {background:#FFEAAB;text-align:left;padding:8px;font-size:9px;} .data td {padding:9px 8px;border-bottom:1px solid #E8D8B2;vertical-align:top;word-wrap:break-word;} .data th:last-child,.data td:last-child {width:75px;} .person {margin-bottom:10px;border:1px solid #E8D8B2;padding:10px;page-break-inside:avoid;} .person p {margin:3px 0;} .small {font-size:8px;color:#67553B;} .photo {max-width:100%;max-height:220px;} .footer {position:fixed;bottom:-62px;left:0;right:0;border-top:2px solid #DAA520;padding-top:8px;height:48px;font-size:7px;color:#67553B;} .footer p {margin:0 80px 3px 0;} .keep {page-break-inside:avoid;} .excerpt {white-space:pre-wrap;word-wrap:break-word;}
.consent-grid {width:100%;table-layout:fixed;border-collapse:collapse;} .consent-grid td {width:50%;vertical-align:top;padding-right:8px;} .consent-grid tr {page-break-inside:avoid;} </style></head><body><div class="footer"><p><strong>okwethu</strong> | <?= $e($story['id']) ?> | Exported <?= $e($issued) ?></p><p><?= $e(Copy::LIMITS) ?></p><p>Demo ledger: no real money moves. Scan the QR for the current record.</p></div>
<div class="topbar"></div><img class="brand" src="<?= $e($logo) ?>" alt="Okwethu"><div class="hero"><span class="eyebrow">STORY PASSPORT</span><h1><?= $e($title) ?></h1><p class="value"><?= $e($story['creator']['name']) ?></p><p class="tag"><?= $e(Copy::STATUS[$story['status']]) ?><?= $restricted ? ' | Restricted' : '' ?></p></div>
<table class="meta"><tr><td><span class="label">Passport ID</span><br><span class="value"><?= $e($story['id']) ?></span></td><td><span class="label">Registered (UTC)</span><br><?= $e(substr($story['createdAt'], 0, 10)) ?></td></tr><?php if (!$restricted): ?><tr><td><span class="label">Language / format</span><br><?= $e($story['language']) ?> / <?= $e(ucfirst($story['mediaType'])) ?></td><td><span class="label">Coarse place</span><br><?= $e($story['placeCoarse'] ?: 'Not provided') ?></td></tr><?php endif ?><tr><td colspan="2"><span class="label">Steward contact</span><br><?= $e($story['contactEmail']) ?></td></tr></table>
<table class="qr-card"><tr><td style="width:75%"><span class="eyebrow">KEEP THE PEOPLE WITH THE STORY</span><p><strong>Scan for the live passport.</strong></p><p class="small">This PDF is a snapshot. Consent and review status may change. Check the current record before use.</p><a href="<?= $e($url) ?>"><?= $e($url) ?></a></td><td class="qr-cell"><img class="qr" src="<?= $e($qr) ?>" alt="Passport QR"></td></tr></table>
<?php if ($restricted): ?><div class="notice"><h2>Held with care.</h2><p><?= $e(Copy::RESTRICTED) ?></p></div><?php else: ?>
<h2>Context from the steward</h2><p class="excerpt"><?= $e($story['contextNote']) ?></p>
<?php if ($image): ?><div class="keep"><h2>Story image</h2><img class="photo" src="<?= $e($image) ?>" alt="Story image with passport QR"></div><?php elseif ($story['mediaType'] === 'text'): ?><h2><?= mb_strlen($story['textBody']) > 1800 ? 'Story excerpt' : 'Story' ?></h2><p class="excerpt"><?= $e(mb_substr($story['textBody'], 0, 1800)) ?></p><?php if (mb_strlen($story['textBody']) > 1800): ?><p class="small">Excerpt only. Open the live passport for the complete story.</p><?php endif ?><?php else: ?><p class="notice">Audio and video are available on the live passport. This PDF contains their declared record, not the media file.</p><?php endif ?>
<h2>Declared terms</h2><ul><?php foreach (Rules::license($story['license']['preset'], $story['license']['aiTrainingAllowed']) as $line): ?><li><?= $e($line) ?></li><?php endforeach ?></ul><?php if ($story['license']['notes']): ?><p><?= $e($story['license']['notes']) ?></p><?php endif ?>
<h2>Declared revenue shares</h2><p class="small">Demo allocations only. These percentages do not represent an actual payment.</p><table class="data"><thead><tr><th>Contributor / role</th><th>Share</th></tr></thead><tbody><?php foreach ($story['shares'] as $share): $person = array_values(array_filter($story['contributors'], static fn(array $p): bool => $p['id'] === $share['contributorId']))[0]; ?><tr><td><strong><?= $e($person['name']) ?></strong><br><?= $e($person['role']) ?></td><td><?= $e(number_format($share['bps'] / 100, 2)) ?>%</td></tr><?php endforeach ?></tbody></table>
<h2>Consent, person by person</h2><table class="consent-grid"><tbody><?php foreach (array_chunk($story['contributors'], 2) as $pair): ?><tr><?php foreach ($pair as $person): ?><td><div class="person"><strong><?= $e($person['name']) ?></strong><p class="small"><?= $e($person['role']) ?></p><?php foreach (Copy::PURPOSES as $purpose => $label): $consent = $person['consents'][$purpose] ?? null; ?><p class="small"><?= $e($label) ?>: <strong><?= ($consent['granted'] ?? false) ? 'Granted' : 'Not granted' ?></strong><?= $consent ? ' | ' . $e(substr($consent['recordedAt'], 0, 10)) : '' ?></p><?php endforeach ?></div></td><?php endforeach ?><?php if (count($pair) === 1): ?><td></td><?php endif ?></tr><?php endforeach ?></tbody></table><?php endif ?><div class="notice"><strong>A declared record, with honest limits.</strong><p><?= $e(Copy::LIMITS) ?></p><p>Identity and authority to speak for a community are not independently verified.</p></div></body></html>

